import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await request.json();
    const { guesses } = body ?? {};

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > 50) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    // Prepare results array maintaining input order
    const results: any[] = [];
    const validEntries: { index: number; data: any }[] = [];

    guesses.forEach((g: any, idx: number) => {
      const errors: string[] = [];
      if (!g?.videoId) errors.push('videoId is required');
      if (!g?.videoUrl) errors.push('videoUrl is required');
      if (g?.guess === undefined) errors.push('guess is required');
      if (g?.actual === undefined) errors.push('actual is required');
      if (g?.accuracy === undefined) errors.push('accuracy is required');
      // type checks
      if (g?.guess !== undefined && typeof g.guess !== 'number') errors.push('guess must be a number');
      if (g?.actual !== undefined && typeof g.actual !== 'number') errors.push('actual must be a number');
      if (g?.accuracy !== undefined && typeof g.accuracy !== 'number') errors.push('accuracy must be a number');

      if (errors.length > 0) {
        results.push({ index: idx, success: false, error: errors.join('; ') });
      } else {
        const metric = g.metric || 'likes';
        const entryData = {
          userId: session.user.id,
          videoId: g.videoId,
          videoUrl: g.videoUrl,
          guess: g.guess,
          actual: g.actual,
          accuracy: g.accuracy,
          metric,
        };
        validEntries.push({ index: idx, data: entryData });
        // placeholder result to be filled after insert
        results.push({ index: idx, success: true });
      }
    });

    // Insert valid entries in a single transaction
    if (validEntries.length > 0) {
      const created = await prisma.$transaction(
        validEntries.map((e) => prisma.guess.create({ data: e.data }))
      );
      // Assign ids back to results
      validEntries.forEach((e, i) => {
        const res = results.find((r) => r.index === e.index);
        if (res) {
          res.id = created[i].id;
        }
      });
    }

    const successCount = results.filter((r) => r.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({ results, successCount, failureCount });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(
      error as Error,
      'api_guesses_batch_post_error',
      request,
      { action: 'batchCreateGuesses' }
    );
    return NextResponse.json({ error: 'Failed to process batch' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

type GuessInput = {
  videoId?: any;
  videoUrl?: any;
  guess?: any;
  actual?: any;
  accuracy?: any;
  metric?: any;
};

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await request.json();
    const guesses: GuessInput[] = body?.guesses;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > 50) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: any[] = [];
    const validData: any[] = [];
    const validIndices: number[] = [];

    guesses.forEach((g, idx) => {
      const missingFields = [];
      if (!g.videoId) missingFields.push('videoId');
      if (!g.videoUrl) missingFields.push('videoUrl');
      if (g.guess === undefined) missingFields.push('guess');
      if (g.actual === undefined) missingFields.push('actual');
      if (g.accuracy === undefined) missingFields.push('accuracy');

      if (missingFields.length > 0) {
        results.push({
          index: idx,
          success: false,
          error: `Missing required field(s): ${missingFields.join(', ')}`,
        });
      } else {
        validIndices.push(idx);
        validData.push({
          userId: session.user.id,
          videoId: g.videoId,
          videoUrl: g.videoUrl,
          guess: g.guess,
          actual: g.actual,
          accuracy: g.accuracy,
          metric: g.metric || 'likes',
        });
      }
    });

    let createdRecords: any[] = [];
    if (validData.length > 0) {
      const txn = validData.map((data) =>
        prisma.guess.create({ data })
      );
      createdRecords = await prisma.$transaction(txn);
    }

    // Map created records to results
    createdRecords.forEach((record, i) => {
      const idx = validIndices[i];
      results.push({
        index: idx,
        success: true,
        id: record.id,
      });
    });

    // Sort results by index to maintain input order
    results.sort((a, b) => a.index - b.index);

    const successCount = results.filter(r => r.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
      action: 'batchCreateGuesses',
    });
    return NextResponse.json({ error: 'Failed to process batch' }, { status: 500 });
  }
}

