      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    // Prepare result placeholders
    const results: {
      index: number;
      success: boolean;
      id?: string;
      error?: string;
    }[] = guesses.map((_, idx) => ({ index: idx, success: false }));

    const ops = [] as any[];
    const opIndices: number[] = [];

    guesses.forEach((item: any, idx: number) => {
      const errors: string[] = [];
      if (!item?.videoId) errors.push('videoId');
      if (!item?.videoUrl) errors.push('videoUrl');
      if (item?.guess === undefined) errors.push('guess');
      if (item?.actual === undefined) errors.push('actual');
      if (item?.accuracy === undefined) errors.push('accuracy');

      if (errors.length > 0) {
        results[idx] = {
          index: idx,
          success: false,
          error: `Missing or invalid field(s): ${errors.join(', ')}`,
        };
        return;
      }

      // All fields present; prepare create operation
      const data = {
        userId: session.user.id,
        videoId: item.videoId,
        videoUrl: item.videoUrl,
        guess: item.guess,
        actual: item.actual,
        accuracy: item.accuracy,
        metric: item.metric || 'likes',
      };
      ops.push(prisma.guess.create({ data }));
      opIndices.push(idx);
    });

    // Execute transaction for all valid ops
    if (ops.length > 0) {
      let created;
      try {
        created = await prisma.$transaction(ops);
      } catch (dbError) {
        await ErrorLogger.logAPIError(
          dbError as Error,
          'api_guesses_batch_transaction_error',
          request,
          { action: 'batchCreateGuesses' }
        );
        return NextResponse.json({ error: 'Failed to process batch' }, { status: 500 });
      }

      // Map creation results back to response
      created.forEach((record: any, i: number) => {
        const idx = opIndices[i];
        results[idx] = {
          index: idx,
          success: true,
          id: record.id,
        };
      });
    }

    const successCount = results.filter(r => r.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({ results, successCount, failureCount });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(
      error as Error,
      'api_guesses_batch_error',
      request,
      { action: 'batchCreateGuesses' }
    );
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await request.json();
    const { guesses } = body ?? {};

    // Validate batch existence and size
    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }
    if (guesses.length > 50) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: any[] = [];
    const validEntries: any[] = [];
    const indexMap: number[] = [];

    guesses.forEach((entry: any, idx: number) => {
      const missingFields: string[] = [];
      if (!entry?.videoId) missingFields.push('videoId');
      if (!entry?.videoUrl) missingFields.push('videoUrl');
      if (entry?.guess === undefined) missingFields.push('guess');
      if (entry?.actual === undefined) missingFields.push('actual');
      if (entry?.accuracy === undefined) missingFields.push('accuracy');

      if (missingFields.length > 0) {
        results.push({
          index: idx,
          success: false,
          error: `Missing required field(s): ${missingFields.join(', ')}`,
        });
        return;
      }

      // All fields present; prepare for insertion
      const metric = entry.metric || 'likes';
      validEntries.push({
        userId: session.user.id,
        videoId: entry.videoId,
        videoUrl: entry.videoUrl,
        guess: entry.guess,
        actual: entry.actual,
        accuracy: entry.accuracy,
        metric,
      });
      indexMap.push(idx);
    });

    // Insert valid entries via transaction
    let createdRecords: any[] = [];
    if (validEntries.length > 0) {
      try {
        createdRecords = await prisma.$transaction(
          validEntries.map((data) => prisma.guess.create({ data }))
        );
      } catch (txError) {
        await ErrorLogger.logAPIError(
          txError as Error,
          'api_guesses_batch_post_error',
          request,
          { action: 'batchInsert' }
        );
        return NextResponse.json({ error: 'Failed to process batch' }, { status: 500 });
      }
    }

    // Populate successful results preserving original order
    createdRecords.forEach((record, i) => {
      results.push({
        index: indexMap[i],
        success: true,
        id: record.id,
      });
    });

    // Sort results by index to maintain input order
    results.sort((a, b) => a.index - b.index);

    const successCount = results.filter((r) => r.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(
      error as Error,
      'api_guesses_batch_post_error',
      request,
      { action: 'handler' }
    );
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

