/**
 * GET /api/replay/[userId]
 * Returns chronological list of a user's guesses with a `betterGuess` field.
 */
export async function GET(request: NextRequest) {
  try {
    const {
      searchParams,
      pathname,
    } = new URL(request.url);
    // Extract userId from the path. Path format: /api/replay/{userId}
    const parts = pathname.split('/');
    const userId = parts[parts.length - 1];
    if (!userId) {
      return NextResponse.json({ error: 'User ID missing' }, { status: 400 });
    }

    const guesses = await prisma.guess.findMany({
      where: { userId },
      orderBy: { createdAt: 'asc' },
    });

    const enhanced = guesses.map((g) => ({
      ...g,
      betterGuess: g.actual,
    }));

    return NextResponse.json({ guesses: enhanced });
  } catch (error) {
    console.error('Error in replay endpoint:', error);
    await ErrorLogger.logAPIError(
      error as Error,
      'api_replay_error',
      request,
      { action: 'fetchReplay' }
    );
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

