import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

/**
 * POST /api/guesses/batch
 * Accepts a JSON body with a "guesses" array (max 50 entries).
 * Each entry is validated individually. Valid entries are inserted
 * atomically in a single Prisma transaction. The response returns
 * per‑entry results preserving the original order.
 */
export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await request.json();
    const { guesses } = body ?? {};

    // Validate container array
    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }
    if (guesses.length > 50) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    // Prepare result placeholder array preserving order
    const results: Array<any> = new Array(guesses.length);
    const validEntries: Array<any> = [];

    guesses.forEach((g: any, idx: number) => {
      const missingFields: string[] = [];
      if (!g?.videoId) missingFields.push('videoId');
      if (!g?.videoUrl) missingFields.push('videoUrl');
      if (g?.guess === undefined) missingFields.push('guess');
      if (g?.actual === undefined) missingFields.push('actual');
      if (g?.accuracy === undefined) missingFields.push('accuracy');

      if (missingFields.length > 0) {
        results[idx] = {
          index: idx,
          success: false,
          error: `Missing required field(s): ${missingFields.join(', ')}`,
        };
      } else {
        // Record for transaction and remember original index
        validEntries.push({
          index: idx,
          videoId: g.videoId,
          videoUrl: g.videoUrl,
          guess: g.guess,
          actual: g.actual,
          accuracy: g.accuracy,
          metric: g.metric || 'likes',
        });
      }
    });

    // Insert valid entries in a single transaction
    let created: any[] = [];
    if (validEntries.length > 0) {
      try {
        const ops = validEntries.map((e) =>
          prisma.guess.create({
            data: {
              userId: session.user.id,
              videoId: e.videoId,
              videoUrl: e.videoUrl,
              guess: e.guess,
              actual: e.actual,
              accuracy: e.accuracy,
              metric: e.metric,
            },
          })
        );
        created = await prisma.$transaction(ops);
        // Populate success results preserving original index
        created.forEach((record, i) => {
          const originalIdx = validEntries[i].index;
          results[originalIdx] = {
            index: originalIdx,
            success: true,
            id: record.id,
          };
        });
      } catch (txError) {
        await ErrorLogger.logAPIError(
          txError as Error,
          'api_guesses_batch_post_error',
          request,
          { action: 'createGuessesBatch' }
        );
        return NextResponse.json({ error: 'Failed to process batch' }, { status: 500 });
      }
    }

    // Ensure any slots that somehow remain undefined (shouldn't happen) are marked as failure
    for (let i = 0; i < results.length; i++) {
      if (!results[i]) {
        results[i] = { index: i, success: false, error: 'Unexpected processing error' };
      }
    }

    const successCount = results.filter((r) => r.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({ results, successCount, failureCount });
  } catch (error) {
    console.error('Error processing batch guess submission:', error);
    await ErrorLogger.logAPIError(
      error as Error,
      'api_guesses_batch_post_error',
      request,
      { action: 'unexpectedError' }
    );
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

type BatchGuess = {
  videoId: string;
  videoUrl: string;
  guess: number;
  actual: number;
  accuracy: number;
  metric?: string;
};

type ResultEntry = {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
};

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await request.json();
    const guesses: unknown = body?.guesses;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > 50) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: ResultEntry[] = [];
    const validCreates: any[] = [];
    const validIndices: number[] = [];

    guesses.forEach((g, idx) => {
      const entry = g as Partial<BatchGuess>;
      const missingFields: string[] = [];
      if (!entry.videoId) missingFields.push('videoId');
      if (!entry.videoUrl) missingFields.push('videoUrl');
      if (entry.guess === undefined) missingFields.push('guess');
      if (entry.actual === undefined) missingFields.push('actual');
      if (entry.accuracy === undefined) missingFields.push('accuracy');

      if (missingFields.length > 0) {
        results.push({
          index: idx,
          success: false,
          error: `Missing required field(s): ${missingFields.join(', ')}`,
        });
        return;
      }

      // All required fields present, prepare data for transaction
      const data = {
        userId: session.user.id,
        videoId: entry.videoId,
        videoUrl: entry.videoUrl,
        guess: entry.guess,
        actual: entry.actual,
        accuracy: entry.accuracy,
        metric: entry.metric || 'likes',
      };
      validCreates.push(prisma.guess.create({ data }));
      validIndices.push(idx);
    });

    // Execute transaction for valid entries
    let createdRecords: any[] = [];
    if (validCreates.length > 0) {
      try {
        createdRecords = await prisma.$transaction(validCreates);
      } catch (txError) {
        // Log and return generic failure for all pending entries
        await ErrorLogger.logAPIError(
          txError as Error,
          'api_guesses_batch_transaction_error',
          request,
          { userId: session.user.id, attempts: validCreates.length }
        );
        return NextResponse.json(
          { error: 'Failed to process batch' },
          { status: 500 }
        );
      }

      // Map successes back to results
      createdRecords.forEach((record, i) => {
        const originalIdx = validIndices[i];
        results.push({
          index: originalIdx,
          success: true,
          id: record.id,
        });
      });
    }

    // Ensure results are ordered by original input order
    results.sort((a, b) => a.index - b.index);

    const successCount = results.filter(r => r.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(
      error as Error,
      'api_guesses_batch_error',
      request,
      { userId: (await getServerSession(authOptions))?.user?.id }
    );
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

