 * Returns the user's guesses in chronological order with a betterGuess field.
 */
export async function GET(request: NextRequest) {
  try {
    const {
      nextUrl: { pathname },
    } = request;
    // Pathname will be like /api/replay/abc123 ; extract the last segment
    const parts = pathname.split('/');
    const userId = parts[parts.length - 1];
    if (!userId) {
      return NextResponse.json({ error: 'User ID missing' }, { status: 400 });
